/* Synthetic producer: delays must survive the complete cost boundary. */
#include <gtk/gtk.h>
#include <stdlib.h>
static GAsyncQueue *queue;static GtkWidget *image;static unsigned generation;
typedef struct {int action;unsigned delay;} Job;
static gboolean result(gpointer data){Job *job=data;GdkPixbuf *pixels=gdk_pixbuf_new(GDK_COLORSPACE_RGB,TRUE,8,320,240);gdk_pixbuf_fill(pixels,job->action==3?0x5599ffff:0x9955ffff);gtk_image_set_from_pixbuf(GTK_IMAGE(image),pixels);g_object_unref(pixels);generation++;char text[512];g_snprintf(text,sizeof(text),"[host]\nsequence=%u\ngeneration=%u\nframe_generation=%u\nshelf_generation=1\nbook=1\npage=%u\nfont=%u\nshelf_restoring=0\n",generation,generation,generation,generation,generation+24);g_file_set_contents(g_getenv("F08_CONTROL_STATE"),text,-1,NULL);g_free(job);return G_SOURCE_REMOVE;}
static gpointer work(gpointer data){(void)data;for(;;){Job *job=g_async_queue_pop(queue);if(job->action==0){g_free(job);break;}g_usleep(job->delay);g_idle_add(result,job);}return NULL;}
static gboolean submit(gpointer data){unsigned n=GPOINTER_TO_UINT(data);Job *job=g_new0(Job,1);job->action=n==1?3:5;job->delay=n==1?50000:80000;g_async_queue_push(queue,job);return G_SOURCE_REMOVE;}
static gboolean finish(gpointer data){(void)data;gtk_main_quit();return G_SOURCE_REMOVE;}
int main(int argc,char **argv){gtk_init(&argc,&argv);GtkWidget *window=gtk_window_new(GTK_WINDOW_TOPLEVEL);gtk_window_set_title(GTK_WINDOW(window),"EXReader Linux");image=gtk_image_new();atk_object_set_name(gtk_widget_get_accessible(image),"Rendered reading page; selectable text and notes are in More");gtk_container_add(GTK_CONTAINER(window),image);gtk_widget_show_all(window);queue=g_async_queue_new();GThread *thread=g_thread_new("control",work,NULL);g_timeout_add(100,submit,GUINT_TO_POINTER(1));g_timeout_add(400,submit,GUINT_TO_POINTER(2));g_timeout_add(1600,finish,NULL);gtk_main();Job *stop=g_new0(Job,1);g_async_queue_push(queue,stop);g_thread_join(thread);gtk_widget_destroy(window);g_async_queue_unref(queue);return generation==2?0:1;}
